package pe.ganadoconecta.modulos.reproduccion.dominio;
import java.text.Normalizer;import java.time.*;import java.util.*;
public record Parto(UUID id,UUID ganaderiaId,UUID madreId,UUID padreId,LocalDate fecha,ResultadoParto resultado,String observaciones,List<UUID> criaIds,UUID creadoPor,Instant creadoEn){public Parto{if(id==null||id.version()!=4)throw new DatoReproductivoInvalidoException("partoId");Objects.requireNonNull(ganaderiaId);Objects.requireNonNull(madreId);if(fecha==null)throw new DatoReproductivoInvalidoException("fecha");Objects.requireNonNull(resultado);criaIds=criaIds==null?List.of():List.copyOf(criaIds);if(new HashSet<>(criaIds).size()!=criaIds.size()||criaIds.contains(madreId)||criaIds.stream().anyMatch(Objects::isNull))throw new DatoReproductivoInvalidoException("criaIds");if((resultado==ResultadoParto.CON_CRIAS_REGISTRADAS)!=!criaIds.isEmpty())throw new DatoReproductivoInvalidoException("resultado");observaciones=texto(observaciones);Objects.requireNonNull(creadoPor);Objects.requireNonNull(creadoEn);}public void validarNoFuturo(LocalDate hoy){if(fecha.isAfter(hoy))throw new DatoReproductivoInvalidoException("fecha");}private static String texto(String v){if(v==null)return null;String n=Normalizer.normalize(v,Normalizer.Form.NFC).strip();if(n.isEmpty())return null;if(n.codePointCount(0,n.length())>2000||n.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\r'))throw new DatoReproductivoInvalidoException("observaciones");return n;}}
